"""Regression: free text in proposals is generated by the application from verified facts, never by the model.

Background: in the first live run the model wrote a ticket note that said "...per company policy". Nothing in the
telemetry mentions any policy, so that was an unsupported claim reaching an approver and a downstream system.
"""
from __future__ import annotations

import json
import re

import pytest

from fleet_copilot import actions, db, notes
from fleet_copilot.graph import FleetAgent
from fleet_copilot.tools import TicketArgs

from .fakes import ScriptedLLM, ai, call, final_from_last_result, need, plan
from .helpers import latest_id, sess, supported_cases

# Phrases the data cannot support. None may ever appear in generated text.
UNSUPPORTED = re.compile(r"polic(y|ies)|company|corporate|mandatory|must |required|deadline|immediately|urgent|"
                         r"violation|security risk|breach|consequence", re.I)


@pytest.fixture
def conn():
    c = db.connect(":memory:")
    db.load_ndjson(c)
    db.seed_admins(c)
    return c


def test_ticket_note_matches_the_agreed_template():
    assert notes.ticket_note("1LYSSFD074BB", "screen_lock", "2026-06-12T09:47:00Z") == (
        "Review the screen-lock configuration on 1LYSSFD074BB. The latest telemetry snapshot "
        "(2026-06-12T09:47:00Z) reports a failed screen_lock check.")
    assert "operating-system update" in notes.ticket_note("D", "os_up_to_date", "t")
    assert "foo bar" in notes.ticket_note("D", "foo_bar", "t")          # unknown checks still get a plain label


def test_the_ticket_tool_has_no_free_text_field():
    assert set(TicketArgs.model_fields) == {"device_id", "check_id", "evidence"}


@pytest.mark.parametrize("name", ["ticket", "upgrade_ram", "upgrade_storage", "replace_battery",
                                  "replace_ram_soldered", "replace_storage_soldered", "notify"])
def test_no_generated_text_makes_an_unsupported_claim(conn, name):
    company, action, args, evidence = supported_cases(conn)[name]
    r = actions.propose(conn, sess(company), action, args, evidence)
    assert r.status == "pending"
    p = actions.get_proposal(conn, company, r.proposal_id)
    prose = [p["justification"]] + [v for k, v in p["args"].items() if k in ("note", "reason", "message")]
    assert prose and all(prose)
    for text in prose:
        assert not UNSUPPORTED.search(text), f"unsupported wording in generated text: {text!r}"


def test_generated_text_contains_only_verified_facts(conn):
    company, action, args, evidence = supported_cases(conn)["notify"]
    r = actions.propose(conn, sess(company), action, args, evidence)
    msg = actions.get_proposal(conn, company, r.proposal_id)["args"]["message"]
    snap = conn.execute("SELECT collected_at, model_name FROM snapshots WHERE snapshot_id=?", (evidence[0],)).fetchone()
    assert snap["model_name"] in msg and snap["collected_at"] in msg and "8NM23J95R5I6" in msg
    assert "screen-lock check (screen_lock) is failing" in msg


def test_a_model_that_writes_its_own_note_is_stopped_in_the_graph(conn):
    """The exact failure from the first live run, replayed against a model that tries it again."""
    device, evid = "1LYSSFD074BB", latest_id(conn, "acme-001", "1LYSSFD074BB")
    sneaky = ai(call("open_remediation_ticket", {
        "device_id": device, "check_id": "screen_lock", "evidence": [evid],
        "note": "Please enable/enforce a screen lock timeout and password requirement per company policy.",
        "justification": "Required by company policy."}))
    honest = ai(call("open_remediation_ticket", {"device_id": device, "check_id": "screen_lock", "evidence": [evid]}))
    llm = ScriptedLLM([plan("ticket", [need("devices_state")], True),
                       ai(call("query_devices", {"failing_check": "screen_lock"})),
                       sneaky,                                   # rejected: unknown fields
                       honest,                                   # accepted: identifiers only
                       final_from_last_result("Proposed a ticket.")])
    agent = FleetAgent(conn, sess("acme-001"), llm)
    out = agent.ask("Open a screen_lock ticket for 1LYSSFD074BB")

    rejected = [t for t in out.trace if t.get("tool") == "open_remediation_ticket" and "error" in t]
    assert len(rejected) == 1 and "note" in rejected[0]["error"]
    assert conn.execute("SELECT COUNT(*) FROM proposals").fetchone()[0] == 1       # only the honest one exists
    stored = json.dumps(out.pending[0]).lower() + out.rendered.lower()
    assert "per company policy" not in stored and "policy" not in stored
    assert out.pending[0]["args"]["note"].startswith("Review the screen-lock configuration on 1LYSSFD074BB.")
